      { text: "But to the rest I—not the Lord—say, if any brother has an unbelieving wife, and she is content to live with him, let him not leave her. The woman who has an unbelieving husband, and he is content to live with her, let her not leave her husband.", reference: "1 Corinthians 7:12-13", translation: "WEB", theme: "divorce" },
      { text: "Yet if the unbeliever departs, let there be separation. The brother or the sister is not under bondage in such cases, but God has called us in peace.", reference: "1 Corinthians 7:15", translation: "WEB", theme: "divorce" },
      { text: "When a man takes a wife and marries her, then it shall be, if she finds no favor in his eyes, because he has found some unseemly thing in her, that he shall write her a bill of divorce, and put it in her hand, and send her out of his house.", reference: "Deuteronomy 24:1", translation: "WEB", theme: "divorce" },
      { text: "For the woman that has a husband is bound by law to the husband while he lives, but if the husband dies, she is discharged from the law of the husband. So then if, while the husband lives, she is joined to another man, she would be called an adulteress. But if the husband dies, she is free from the law, so that she is no adulteress, though she is joined to another man.", reference: "Romans 7:2-3", translation: "WEB", theme: "divorce" },
      { text: "I saw when, for this very cause, that backsliding Israel had committed adultery, I had put her away and given her a bill of divorce, yet treacherous Judah, her sister, had no fear; but she also went and played the prostitute.", reference: "Jeremiah 3:8", translation: "WEB", theme: "divorce" },
      { text: "And be kind to one another, tender hearted, forgiving each other, just as God also in Christ forgave you.", reference: "Ephesians 4:32", translation: "WEB", theme: "divorce" },
      { text: "And above all things be earnest in your love among yourselves, for love covers a multitude of sins.", reference: "1 Peter 4:8", translation: "WEB", theme: "divorce" }
