      { text: "They will never be hungry, neither thirsty any more; neither will the sun beat on them, nor any heat; for the Lamb who is in the middle of the throne shepherds them, and leads them to springs of life-giving waters. And God will wipe away every tear from their eyes.”", reference: "Revelation 7:16-17", translation: "WEB", theme: "heaven" },
      { text: "But I am in a dilemma between the two, having the desire to depart and be with Christ, which is far better.", reference: "Philippians 1:23", translation: "WEB", theme: "heaven" }
